ORIGINAL = {
    "M199": "#!/usr/bin/env python3\n\"\"\"M199: index-operator-parameterized CMS FSREAD to A-only scratch.\n\nLinux checks IBM assembler form and independent C89 full Git SHA1 parity.\nThe IBM CMS assembler, FSREAD, FSWRITE and LINERD remain TARGET-ONLY.\n\"\"\"\nfrom pathlib import Path\nimport hashlib\nimport subprocess\nimport tempfile\n\nroot=Path(__file__).resolve().parents[1]\nasm=(root/\"src/GITBX9.ASSEMBLE\").read_text()\nrex=(root/\"src/GITB9.EXEC\").read_text()\nsha=(root/\"src/GITVO7M.C\").read_text()\nlines=asm.splitlines()\nassert max(map(len,lines))<=72\nassert max(map(len,rex.splitlines()))<=80\ncontinuations=[row for row in lines if len(row)==72 and row[71]==\"X\"]\nassert len(continuations)==5,continuations\nassert len({row for row in continuations})==4\nlabels=[]\nfor i,row in enumerate(lines,1):\n    if not row or row[0].isspace() or row.startswith(\"*\"):\n        continue\n    label=row.split()[0]\n    assert len(label)<=8,(i,label)\n    assert row[len(label)].isspace(),(i,label)\n    labels.append(label)\nassert len(labels)==len(set(labels)),labels\ncode=\"\\n\".join(x for x in lines if x and not x.startswith(\"*\"))\nassert code.count(\"LINERD DATA=(INBUF,8),TYPE=STACK\")==2\nassert code.count(\"BAL   10,PARSEDEC\")==2\nassert \"PARSEDEC C     0,=F'1'\" in code\nassert \"C     0,=F'8'\" in code\nassert \"C     6,=F'240'\" in code and \"C     6,=F'249'\" in code\nassert \"S     6,=F'240'\" in code and \"MH    5,=H'10'\" in code\nassert \"C     5,=F'3864799'\" in code\nassert \"C     5,=F'64'\" in code\nassert \"C     6,=F'3864799'\" in code\nassert \"LA    6,1(5)\" in code\nassert \"C     6,NRECS\" in code\nassert \"C     6,BODYCNT\" in code\nassert \"C     7,=F'64'\" in code\nassert \"C     4,=F'2048'\" in code\nassert \"CLC   RECSET(4),=C'OBJ '\" in code\nassert \"LENSET   DS    65F\" in code\nassert \"RECSET   DS    CL4160\" in code\n# A 4,160-byte DS moves later labels beyond an S/370 12-bit\n# displacement from the single GITBX9 base register. Keep all\n# referenced constants, texts and FSCB before RECSET.\nhuge=code.index(\"RECSET   DS    CL4160\")\nassert code.index(\"OUTFSCB  FSCB\")<huge\nassert code.index(\"START    DC\")<huge\nassert code.index(\"OCERR    DC\")<huge\nassert code.index(\"LENSET   DS    65F\")<huge\nassert code.index(\"RECSET   DS    CL4160\")<code.index(\n    \"         END   GITBX9\")\nassert \"FSREAD 'M173NET STAGE G1',BUFFER=(4),BSIZE=64\" in code\nassert \"RECFM=V,RECNO=(5),NOREC=1,FORM=E\" in code\nassert \"FSCLOSE 'M173NET STAGE G1',ERROR=ICLERR\" in code\nassert \"FSOPEN FSCB=OUTFSCB,OPENTYP=NEW\" in code\nassert \"FSWRITE FSCB=OUTFSCB,BUFFER=(4),BSIZE=(5)\" in code\nassert \"FSCLOSE FSCB=OUTFSCB,ERROR=OCLERR\" in code\nassert \"FSCB  'GITR199 DATA A1'\" in code\nassert code.index(\"FSCLOSE 'M173NET STAGE G1'\") < code.index(\n    \"FSOPEN FSCB=OUTFSCB,OPENTYP=NEW\")\nassert code.count(\"FSREAD 'M173NET STAGE G1'\")==1\nassert code.count(\"FSWRITE FSCB=OUTFSCB\")==1\nfor bad in (\"FSWRITE 'M173NET\", \"FSERASE\", \"FSPOINT\",\n            \"OPENTYP=REPLACE\", \"OPENTYP=WRITE\",\n            \"FILEDEF STGIN\", \"FORM=S\", \"GITVRAW DATA\"):\n    assert bad not in code,bad\nfor token in (\n    \"'STATE M173NET STAGE G'\", \"'STATE M174NET INDEX G'\",\n    \"'STATE GITR199 DATA A'\", \"'STATE GITBX9 MODULE A'\",\n    \"'STATE GITVO7M MODULE A'\", \"'GITBX9'\",\n    \"queue head\", \"queue count\",\n    \"'PIPE CMS FILEDEF | STEM f.'\",\n    \"'FILEDEF OBJIN DISK GITR199 DATA A'\",\n    \"'GITVO7M VERIFY' obj oid\",\n    \"'FILEDEF OBJIN CLEAR'\",\n    \"M199 PARAMETERIZED FULL OID PASS G\",\n    \"M199 SCRATCH EXISTS - REFUSE OVERWRITE\",\n    \"M199 LEAVE POSSIBLE PARTIAL SCRATCH UNCHANGED\",\n):\n    assert token in rex,token\nassert \"head+count>3864799\" in rex\nassert \"count<1 | count>64\" in rex\nassert not (root/\"src/GITBX9.EXEC\").exists()\nassert not (root/\"src/GITB9.ASSEMBLE\").exists()\nassert 'fopen(\"dd:OBJIN\",\"r\")' in sha\n\ndef oid(t,body):\n    kind={1:b\"commit\",2:b\"tree\",3:b\"blob\",4:b\"tag\"}[t]\n    return hashlib.sha1(kind+b\" \"+str(len(body)).encode(\"ascii\")+\n                        bytes([0])+body).hexdigest().upper()\n\ndef records(t,n,body):\n    dig=oid(t,body)\n    h=\"OBJ %d %d %d %s\"%(n,t,len(body),dig)\n    hx=body.hex().upper()\n    return [h]+([hx[x:x+64] for x in range(0,len(hx),64)]\n                if hx else [\"\"]),dig\n\ndef valid(records,expected):\n    n=len(records)-1\n    if n<1 or n>64 or not records[0].startswith(\"OBJ \"):\n        return False\n    total=0\n    for i,row in enumerate(records[1:]):\n        if not 0<len(row)<=64 or len(row)%2:\n            return False\n        if i<n-1 and len(row)!=64:\n            return False\n        if any(c not in \"0123456789ABCDEFabcdef\" for c in row):\n            return False\n        total+=len(row)//2\n    return total==expected and 0<total<=2048\n\nwith tempfile.TemporaryDirectory(prefix=\"m199-\") as dn:\n    d=Path(dn)\n    native=d/\"verify\"\n    subprocess.run([\"gcc\",\"-x\",\"c\",\"-std=c89\",\"-Wall\",\"-Wextra\",\"-Werror\",\n                    str(root/\"src/GITVO7M.C\"),\"-o\",str(native)],\n                   check=True)\n    src=d/\"readonly-stage\"\n    target=d/\"dd:OBJIN\"\n    tests=[(1,3,1, b\"a\"),(3868,1,1969357,b\"parent \"+b\"0\"*40+b\"\\n\"),\n           (7736,2,3864789,bytes((k*19+7)%256 for k in range(291)))]\n    tests += [(100+i,3,200000+i*10,bytes((j*13+i)%256\n              for j in range(size)))\n              for i,size in enumerate((2,31,32,33,63,64,65,289,320,\n                                       511,512,1023,1024,2048),1)]\n    for number,typ,header,body in tests:\n        rows,expected_oid=records(typ,number,body)\n        count=len(rows)-1\n        assert 1<=header<=3864799 and header+count<=3864799\n        assert valid(rows,len(body))\n        src.write_text(\"\\n\".join(rows)+\"\\n\")\n        sha_before=hashlib.sha256(src.read_bytes()).hexdigest()\n        assert not target.exists()\n        target.write_bytes(src.read_bytes())\n        result=subprocess.run([str(native),\"VERIFY\",str(number),\n                               expected_oid],cwd=d,text=True,\n                              capture_output=True)\n        assert result.returncode==0,(number,result.stdout,result.stderr)\n        assert \"M197 READ ONLY FULL OBJECT SHA1 PASS\" in result.stdout\n        assert \"M197 VERIFIED OID \"+expected_oid in result.stdout\n        assert hashlib.sha256(src.read_bytes()).hexdigest()==sha_before\n        target.unlink()\n        cases=(rows[:-1],\n               rows[:1]+[rows[1][:-1]]+rows[2:],\n               rows[:1]+[\"G\"+rows[1][1:]]+rows[2:],\n               rows+[\"AA\"])\n        for bad in cases:\n            if bad==rows:continue\n            if len(bad)!=len(rows):\n                assert not valid(bad,len(body))\n            elif bad is not rows and bad[1]!=rows[1]:\n                assert not valid(bad,len(body))\n    # Bounded record number parse with eight EBCDIC decimal bytes.\n    for text in (\"1\",\"3864789\",\"3864799\",\"64\",\"00000001\",\"00000064\"):\n        assert 1<=len(text)<=8\n        assert all(0xF0<=c<=0xF9 for c in text.encode(\"cp037\"))\n    for text in (\"\", \"123456789\", \"-1\", \"12A\", \"12.0\", \" \"):\n        assert not (1<=len(text)<=8 and all(\n            0xF0<=c<=0xF9 for c in text.encode(\"cp037\")))\nprint(\"M199 HOST STRICT READ ONLY ORIGINAL STAGE MACRO GUARDS PASS\")\nprint(\"M199 HOST INDEX-SPAN BOUNDS, 65 RECORD SLOTS AND OID SHA PASS\")\nprint(\"M199 HOST NEGATIVE TRUNCATION/HEX/RECORD COUNT PASS\")\nprint(\"M199 IBM CMS TARGET ASSEMBLY AND RUNTIME NOT YET VALIDATED\")\n",
    "M200": "#!/usr/bin/env python3\n\"\"\"M200 CMS filedef syntax and exact-name A1 cleanup safety gate.\"\"\"\nfrom pathlib import Path\nimport re\n\nROOT=Path(__file__).resolve().parents[1]\nsource=(ROOT/\"src/GITCLN.EXEC\").read_text()\nassert max(len(s) for s in source.splitlines())<=80\nassert \"parse upper arg mode extra\" in source\nassert \"mode\\\\='SCRATCH' & mode\\\\='RETIRED'\" in source\nassert \"'QUERY DISK A'\" in source\nassert \"'PIPE CMS FILEDEF | STEM defs.'\" in source\nassert \"M200 FILEDEF DISK STILL ACTIVE - REFUSE CLEANUP\" in source\nassert \"word(rec,2)='DISK'\" in source\nassert \"'STATE' filename filetype 'A1'\" in source\nassert \"'ERASE' filename filetype 'A1'\" in source\nassert \"M200 ERASE NOT CONFIRMED\" in source\nassert \"checkrc=28\" in source and \"afterrc\\\\=28\" in source\nassert \"M200 CLEANUP PASS\" in source\nassert \"M200 ERASING EXACT\" in source\n\n# No broad/wildcard erase or any change to the original G stage,\n# index or current active M196/M197/M199 native tools.\nfor forbidden in (\n    \"ERASE *\", \"ERASE G\", \"ERASE' fn ft 'G\",\n    \"ERASE GIT600\", \"M173NET\", \"M174NET\", \"PMAINT\",\n    \"GITBX9\", \"GITB9\", \"GITVO7M\", \"GITRP6M\",\n    \"FORMAT\", \"DIRECTXA\", \"FSWRITE\", \"FSERASE\",\n    \"FILEDEF * CLEAR\", \"ACCESS  ERASE\", \"REPLACE\"\n):\n    assert forbidden not in source, forbidden\ncandidates=re.findall(\n    r\"^ call cleaner '([A-Z0-9]+)','([A-Z0-9]+)'$\",\n    source, flags=re.MULTILINE\n)\nscratches={(\"GITVRAW\",\"DATA\"),(\"GITR199\",\"DATA\")}\nretired={\n (\"GITFSRD\",\"MODULE\"),(\"GITFSP\",\"EXEC\"),\n (\"GITFRB\",\"MODULE\"),(\"GITFRP\",\"EXEC\"),\n (\"GITFL10\",\"MODULE\"),(\"GITFLP\",\"EXEC\"),\n (\"GITBX8\",\"MODULE\"),(\"GITB8\",\"EXEC\"),\n (\"GITFSRD\",\"TEXT\"),(\"GITFRB\",\"TEXT\"),\n (\"GITFL10\",\"TEXT\"),(\"GITBX8\",\"TEXT\"),\n (\"GITFSRD\",\"LISTING\"),(\"GITFRB\",\"LISTING\"),\n (\"GITFL10\",\"LISTING\"),(\"GITBX8\",\"LISTING\")\n}\nassert len(candidates)==len(set(candidates))==len(scratches|retired)\nassert set(candidates)==scratches|retired\nassert all(len(x)<=8 and len(y)<=8 for x,y in candidates)\n# Validate both user-facing modes own exactly their file lists.\nscr=source.split(\"if mode='SCRATCH' then do\",1)[1].split(\n    \"\\nend\\nelse do\",1)[0]\nret=source.split(\"\\nelse do\",1)[1].split(\n    \"\\nend\\nsay 'M200 CLEANUP PASS'\",1)[0]\nassert set(re.findall(r\"call cleaner '([A-Z0-9]+)','([A-Z0-9]+)'\",scr))==scratches\nassert set(re.findall(r\"call cleaner '([A-Z0-9]+)','([A-Z0-9]+)'\",ret))==retired\n\n# Every native wrapper that inspects defined ddnames must invoke\n# the CMS FILEDEF listing command, not ambiguous QUERY FILEDEF.\nfor filename in (\"GITRP6.EXEC\",\"GITB8.EXEC\",\"GITB9.EXEC\",\n                 \"GITVO7.EXEC\"):\n    x=(ROOT/\"src\"/filename).read_text()\n    assert \"'PIPE CMS FILEDEF | STEM f.'\" in x,filename\n    assert \"PIPE CMS QUERY FILEDEF\" not in x,filename\n# Preserve fail-closed native/wrapper success gates and ownership.\np=(ROOT/\"src/GITB9.EXEC\").read_text()\nassert \"'FILEDEF OBJIN CLEAR'\" in p\nassert \"'FILEDEF OBJIN DISK GITR199 DATA A'\" in p\nassert \"if hashrc\\\\=0 | clearrc\\\\=0 then do\" in p\nprint(\"M200 CMS FILEDEF NO-OPERAND LISTING GUARD PASS\")\nprint(\"M200 EXACT A1 SCRATCH FILES AND RETIRED EXEC PROBES WHITELIST PASS\")\nprint(\"M200 ORIGINAL G AND ACTIVE M196/M197/M199 PROTECTED\")\nprint(\"M200 CMS CLEANUP STILL REQUIRES TARGET VALIDATION\")\n",
    "M201": "#!/usr/bin/env python3\n\"\"\"M201: strict C89 index-to-one-line tuple for automatic M199 use.\n\nHost-only: the CMS PIPE/STEM output capture remains a real-CMS gate.\n\"\"\"\nfrom pathlib import Path\nimport hashlib\nimport re\nimport shutil\nimport subprocess\nimport tempfile\n\nroot=Path(__file__).resolve().parents[1]\nnative=(root/\"src/GITP21M.C\").read_text()\nwrap=(root/\"src/GITP21.EXEC\").read_text()\nassert max(map(len,native.splitlines()))<=80\nassert max(map(len,wrap.splitlines()))<=80\nassert 'fopen(\"dd:IDXIN\",\"r\")' in native\nassert 'fopen(\"dd:STGIN\"' not in native\nassert 'fseek(' not in native and 'fwrite(' not in native\nassert 'printf(\"P201 %lu %lu %lu %d %lu \"' in native\nassert 'putchar(\\'\\\\n\\');' in native\nassert 'M201 INDEX INVALID' in native\nassert 'M201 STAGE RECORD COUNT MISMATCH' in native\nassert \"M201 OBJECT EXCEEDS BODY RECORD LIMIT\" in native\nfor needed in (\n    \"'STATE M173NET STAGE G'\",\n    \"'STATE M174NET INDEX G'\",\n    \"'STATE GITP21M MODULE A'\",\n    \"'STATE GITBX9 MODULE A'\",\n    \"'STATE GITVO7M MODULE A'\",\n    \"'STATE GITR199 DATA A'\",\n    \"'PIPE CMS FILEDEF | STEM f.'\",\n    \"'FILEDEF IDXIN DISK M174NET INDEX G'\",\n    \"'PIPE CMS GITP21M PLAN 3864799' obj limit '| STEM p.'\",\n    \"'FILEDEF IDXIN CLEAR'\",\n    \"planrc\\\\=0 | clearrc\\\\=0 | p.0\\\\=1\",\n    \"if tag\\\\='P201' | trailing\\\\='' then exit 8\",\n    \"if pn\\\\=obj | hdr<1 | hdr>3864799 then exit 8\",\n    \"if cnt\\\\=trunc((size+31)/32) then exit 8\",\n    \"'GITB9 G' pn hdr cnt oid\",\n    \"M201 INDEX AUTOMATED FULL SHA PASS G\",\n    \"M201 INDEX ONLY CHECK PASS G\",\n    \"if mode='CHECK' then do\",\n    \"M201 SCRATCH CREATED DURING PLAN - REFUSE\"\n):\n    assert needed in wrap,needed\nfor bad in (\"ERASE \", \"FORMAT \", \"FILEDEF STGIN\",\n            \"OPENTYP=REPLACE\", \"GITVRAW DATA\",\n            \"'GITBX9'\", \"FSWRITE\", \"FILEDEF * CLEAR\"):\n    assert bad not in wrap,bad\nassert not (root/\"src/GITP21M.EXEC\").exists()\n\ndef oid(data):\n    return hashlib.sha1(\n        b\"blob \"+str(len(data)).encode(\"ascii\")+b\"\\0\"+data\n    ).hexdigest().upper()\n\ndef call(prog,wd,*args):\n    return subprocess.run([str(prog), *map(str,args)],\n                          cwd=wd,capture_output=True,text=True)\n\nwith tempfile.TemporaryDirectory(prefix=\"m201-\") as folder:\n    wd=Path(folder)\n    planner,builder=wd/\"planner\",wd/\"builder\"\n    for src,out in ((root/\"src/GITP21M.C\",planner),\n                    (root/\"src/GITPIDX.C\",builder)):\n        subprocess.run([\"gcc\",\"-x\",\"c\",\"-std=c89\",\"-Wall\",\n                        \"-Wextra\",\"-Werror\",str(src),\"-o\",\n                        str(out)],check=True)\n    stage=wd/\"dd:STGIN\"\n    index=wd/\"dd:IDXIN\"\n    rows=[]\n    plans={}\n    for number in range(1,7737):\n        size=(1148 if number==3868 else\n              291 if number==7736 else\n              4+(number*17)%84)\n        # Every object carries a unique binary number prefix.\n        # Otherwise the old periodic fixture produced duplicate\n        # OIDs after the LCM of its length and byte-pattern cycles.\n        body=(number.to_bytes(4,\"big\")+\n              bytes((number+i*19)%256 for i in range(size-4)))\n        plans[number]=(len(rows)+1,(size+31)//32,size,oid(body))\n        rows.append(\"OBJ %d 3 %d %s\"%(number,size,oid(body)))\n        hx=body.hex().upper()\n        rows.extend(hx[x:x+64] for x in range(0,len(hx),64))\n    stage.write_text(\"\\n\".join(rows)+\"\\n\")\n    build=call(builder,wd,\"BUILD\")\n    assert build.returncode==0,build.stdout+build.stderr\n    shutil.copy(wd/\"dd:IDXOUT\",index)\n    orig=hashlib.sha256(stage.read_bytes()).hexdigest()\n    idxhash=hashlib.sha256(index.read_bytes()).hexdigest()\n    # The fixture must satisfy GitPIDX's unique OID requirement.\n    assert len(set(plan[3] for plan in plans.values()))==7736\n    assert wrap.index(\"if mode='CHECK' then do\") < wrap.index(\n        \"'GITB9 G' pn hdr cnt oid\")\n    for number in (1,3868,7736):\n        expected_header,expected_count,size,sha=plans[number]\n        result=call(planner,wd,\"PLAN\",len(rows),number,64)\n        assert result.returncode==0,(number,result.stdout,result.stderr)\n        assert len(result.stdout.splitlines())==1,result.stdout\n        record=result.stdout.strip()\n        assert len(record)<=80,(number,len(record))\n        parts=record.split()\n        assert len(parts)==7,parts\n        marker,obj,header,count,typ,body_size,digest=parts\n        assert marker==\"P201\"\n        assert (int(obj),int(header),int(count),int(typ),\n                int(body_size),digest)==(\n                    number,expected_header,expected_count,3,size,sha)\n        assert re.fullmatch(r\"[0-9A-F]{40}\",digest)\n        if expected_count>1:\n            limited=call(planner,wd,\"PLAN\",len(rows),\n                         number,expected_count-1)\n            assert limited.returncode==8\n            assert \"M201 OBJECT EXCEEDS BODY RECORD LIMIT\" in limited.stdout\n    bad=call(planner,wd,\"PLAN\",len(rows)+1,7736,64)\n    assert bad.returncode==8\n    assert \"M201 STAGE RECORD COUNT MISMATCH\" in bad.stdout\n    bad=call(planner,wd,\"PLAN\",len(rows),7737,64)\n    assert bad.returncode==8\n    bad=call(planner,wd,\"PLAN\",len(rows),3868,0)\n    assert bad.returncode==4\n    damaged=index.read_text().splitlines()\n    pos=next(i for i,x in enumerate(damaged) if x.startswith(\"OID \"))\n    damaged[pos]=damaged[pos].replace(\"OID \",\"OID Z\",1)\n    index.write_text(\"\\n\".join(damaged)+\"\\n\")\n    failed=call(planner,wd,\"PLAN\",len(rows),3868,64)\n    assert failed.returncode==8\n    assert \"M201 INDEX INVALID\" in failed.stdout\n    assert hashlib.sha256(stage.read_bytes()).hexdigest()==orig\n    index.unlink()\n    shutil.copy(wd/\"dd:IDXOUT\",index)\n    assert hashlib.sha256(index.read_bytes()).hexdigest()==idxhash\nprint(\"M201 7736-OBJECT INDEX PARITY AND COMPACT TUPLE PASS\")\nprint(\"M201 FIRST MID LAST SHA/OID/RECORD COUNT HOST PASS\")\nprint(\"M201 FAIL-CLOSED BOUNDS/CORRUPTION AND READ-ONLY G PASS\")\nprint(\"M201 PIPE/STEM CMS CAPTURE AND FULL RUN NOT YET TARGET-TESTED\")\n",
    "M202": "#!/usr/bin/env python3\n\"\"\"M202 host guard: strictly two distinct full SHA objects, cleanup after PASS.\n\nThe real CMS REXX execution remains a separate target-only gate.\n\"\"\"\nfrom pathlib import Path\nfrom dataclasses import dataclass\n\nROOT=Path(__file__).resolve().parents[1]\nrex=(ROOT/\"src/GITC22.EXEC\").read_text()\nassert max(map(len,rex.splitlines()))<=80\nfor token in (\n    \"parse upper arg fm one two limit mode extra\",\n    \"mode\\\\='CHECK' & mode\\\\='RUN'\",\n    \"one=two | limit<1 | limit>64\",\n    \"'STATE GITVRAW DATA A'\",\n    \"M202 OLD M198 SCRATCH EXISTS - REFUSE CLEANUP\",\n    \"'STATE GITR199 DATA A'\",\n    \"M202 OLD M199 SCRATCH EXISTS - REFUSE OVERWRITE\",\n    \"'PIPE CMS FILEDEF | STEM f.'\",\n    \"'GITP21 G' one limit 'CHECK'\",\n    \"'GITP21 G' two limit 'CHECK'\",\n    \"M202 TWO OBJECT INDEX PREFLIGHT PASS\",\n    \"if mode='CHECK' then do\",\n    \"M202 TWO OBJECT CHECK ONLY PASS\",\n    \"M202 TWO OBJECT FULL SHA CLEAN PASS\",\n    \"runone: procedure\",\n    \"'GITP21 G' obj lim\",\n    \"'GITCLN SCRATCH'\",\n    \"M202 SHA FAIL; SCRATCH PRESERVED\",\n    \"M202 SCRATCH CLEAN VERIFIED\",\n):\n    assert token in rex,token\nassert rex.count(\"'GITCLN SCRATCH'\")==1\nassert rex.count(\"'GITP21 G' obj lim\")==1\nassert rex.index(\"M202 TWO OBJECT CHECK ONLY PASS\")<rex.index(\n    \"M202 FIRST OBJECT AUTH BEGIN\")\nrunone=rex.split(\"runone: procedure\",1)[1]\nassert runone.index(\"'GITP21 G' obj lim\")<runone.index(\n    \"'GITCLN SCRATCH'\")\nassert runone.index(\"if objrc\\\\=0 then do\")<runone.index(\n    \"'GITCLN SCRATCH'\")\nassert runone.index(\"if cleanrc\\\\=0 then do\")<runone.index(\n    \"M202 SCRATCH CLEAN VERIFIED\")\nassert rex.index(\"'STATE GITVRAW DATA A'\")<rex.index(\n    \"'GITCLN SCRATCH'\")\nassert \"if rc\\\\=28 then do\" in rex\nfor forbidden in (\n    \"ERASE \", \"FORMAT \", \"FILEDEF * CLEAR\", \"FILEDEF STGIN\",\n    \"FSWRITE\", \"FSCLOSE\", \"GITBX8\", \"GITFL10\",\n    \"GITFSRD\", \"GITFRB\", \"DIRECTXA\", \"PMAINT\",\n    \"GITVRAW DATA A1\", \"M173NET STAGE\", \"M174NET INDEX\",\n    \"GIT600\", \"PIPE CMS GITP21\",\n):\n    assert forbidden not in rex,forbidden\n\n# Outcome-state model of the REXX sequence. Failing an object's\n# full digest MUST NOT erase its diagnostic scratch. A cleanup error\n# is also fatal and blocks any subsequent object's authentication.\n@dataclass\nclass Outcome:\n    statuses: list\n    log: list\n    scratch: bool\n\ndef model(one,two,checks,results,cleans,mode=\"RUN\"):\n    log=[]\n    scratch=False\n    if not 1<=one<=7736 or not 1<=two<=7736 or one==two:\n        return Outcome([\"INVALID\"],log,scratch)\n    log.extend([(\"CHECK\",one),(\"CHECK\",two)])\n    if not all(checks):\n        return Outcome([\"FAIL_PREFLIGHT\"],log,scratch)\n    if mode==\"CHECK\":\n        return Outcome([\"CHECK_ONLY_PASS\"],log,scratch)\n    for index,obj in enumerate((one,two)):\n        log.append((\"SHA\",obj))\n        scratch=True\n        if not results[index]:\n            return Outcome([\"SHA_FAIL\"],log,scratch)\n        log.append((\"CLEAN\",obj))\n        if not cleans[index]:\n            return Outcome([\"CLEAN_FAIL\"],log,scratch)\n        scratch=False\n    return Outcome([\"FULL_PASS\"],log,scratch)\n\nfirst,second=3868,7736\ncases=[\n  ((True,True),(True,True),(True,True),\n   [\"FULL_PASS\"],[(\"CHECK\",3868),(\"CHECK\",7736),\n                  (\"SHA\",3868),(\"CLEAN\",3868),\n                  (\"SHA\",7736),(\"CLEAN\",7736)],False),\n  ((False,True),(True,True),(True,True),\n   [\"FAIL_PREFLIGHT\"],[(\"CHECK\",3868),(\"CHECK\",7736)],False),\n  ((True,True),(False,True),(True,True),\n   [\"SHA_FAIL\"],[(\"CHECK\",3868),(\"CHECK\",7736),\n                 (\"SHA\",3868)],True),\n  ((True,True),(True,False),(True,True),\n   [\"SHA_FAIL\"],[(\"CHECK\",3868),(\"CHECK\",7736),\n                 (\"SHA\",3868),(\"CLEAN\",3868),\n                 (\"SHA\",7736)],True),\n  ((True,True),(True,True),(False,True),\n   [\"CLEAN_FAIL\"],[(\"CHECK\",3868),(\"CHECK\",7736),\n                   (\"SHA\",3868),(\"CLEAN\",3868)],True),\n]\nfor checks,shas,cleans,expect,events,remaining in cases:\n    got=model(first,second,checks,shas,cleans)\n    assert (got.statuses,got.log,got.scratch)==(\n        expect,events,remaining),got\ngot=model(first,second,(True,True),(False,False),(True,True),\n          mode=\"CHECK\")\nassert got.statuses==[\"CHECK_ONLY_PASS\"]\nassert all(ev[0]==\"CHECK\" for ev in got.log)\nassert not got.scratch\nassert model(3868,3868,(True,True),(True,True),\n             (True,True)).statuses==[\"INVALID\"]\nprint(\"M202 HOST TWO DISTINCT INDEX-SELECTED OBJECT GUARDS PASS\")\nprint(\"M202 FULL SHA THEN EXACT SCRATCH CLEANUP ORDER PASS\")\nprint(\"M202 FAILURE PRESERVES SCRATCH; CHECK MODE NO WRITES PASS\")\nprint(\"M202 NO REAL CMS TARGET RUN YET\")\n",
    "M204": "#!/usr/bin/env python3\n\"\"\"M204 index-once bounded plan: strict C89 and fail-closed SHA wrapper.\"\"\"\nfrom pathlib import Path\nimport hashlib\nimport subprocess\nimport tempfile\nimport shutil\n\nroot=Path(__file__).resolve().parents[1]\nsrc=(root/\"src/GITP24M.C\").read_text()\nrex=(root/\"src/GITC24.EXEC\").read_text()\nassert max(map(len,src.splitlines()))<=80\nassert max(map(len,rex.splitlines()))<=80\nassert src.count('fopen(\"dd:IDXIN\",\"r\")')==1\nassert 'fopen(\"dd:STGIN\"' not in src\nassert 'fwrite(' not in src\nassert \"M204 INDEX INVALID\" in src\nassert \"M204 STAGE RECORD COUNT MISMATCH\" in src\nassert \"M204 OBJECT EXCEEDS READER BOUND\" in src\nassert \"if(argc<6||argc>12\" in src\nassert \"allplans(expected,limit,wants,count)\" in src\nassert src.index(\"/* All tuples must pass checks\")<src.index(\n    'printf(\"P201 ')\nfor token in (\n    \"parse upper arg fm mode max objects\",\n    \"count=words(objects)\",\n    \"count<2 | count>8\",\n    \"if obj.i=obj.j then exit 4\",\n    \"'PIPE CMS FILEDEF | STEM f.'\",\n    \"'FILEDEF IDXIN DISK M174NET INDEX G'\",\n    \"'PIPE CMS GITP24M BATCH 3864799' max objects '| STEM plan.'\",\n    \"'FILEDEF IDXIN CLEAR'\",\n    \"readrc\\\\=0 | clearrc\\\\=0 | plan.0\\\\=count\",\n    \"if n\\\\=obj.i | hdr<1 | hdr>3864799 then exit 8\",\n    \"if cnt\\\\=trunc((size+31)/32) then exit 8\",\n    \"'GITB9 G' span.i\",\n    \"M204 SHA FAILED SCRATCH PRESERVED\",\n    \"'GITCLN SCRATCH'\",\n    \"M204 ONE INDEX FULL SHA CLEAN PASS\",\n):\n    assert token in rex,token\nassert rex.count(\"'GITCLN SCRATCH'\")==1\nassert rex.index(\"'GITB9 G' span.i\")<rex.index(\"'GITCLN SCRATCH'\")\nassert rex.index(\"if authrc\\\\=0 then do\")<rex.index(\"'GITCLN SCRATCH'\")\nfor token in (\"ERASE \", \"FSWRITE\", \"FORMAT \", \"PMAINT\", \"GIT600\"):\n    assert token not in rex\n\ndef oid(data):\n    return hashlib.sha1(b\"blob \"+str(len(data)).encode()+\n                        b\"\\0\"+data).hexdigest().upper()\n\nwith tempfile.TemporaryDirectory(prefix=\"m204-\") as td:\n    d=Path(td)\n    planner=d/\"planner\"\n    builder=d/\"builder\"\n    for source,binary in ((root/\"src/GITP24M.C\",planner),\n                          (root/\"src/GITPIDX.C\",builder)):\n        subprocess.run([\"gcc\",\"-x\",\"c\",\"-std=c89\",\"-Wall\",\n                        \"-Wextra\",\"-Werror\",str(source),\n                        \"-o\",str(binary)],check=True)\n    rows=[]\n    items={}\n    for num in range(1,7737):\n        size=1148 if num==3868 else 291 if num==7736 else 4+num%93\n        blob=(num.to_bytes(4,\"big\")+\n              bytes((num*19+k*37)%256 for k in range(size-4)))\n        digest=oid(blob)\n        rec=len(rows)+1\n        count=(size+31)//32\n        items[num]=(rec,count,3,size,digest)\n        rows.append(\"OBJ %d 3 %d %s\"%(num,size,digest))\n        hx=blob.hex().upper()\n        rows.extend(hx[k:k+64] for k in range(0,len(hx),64))\n    (d/\"dd:STGIN\").write_text(\"\\n\".join(rows)+\"\\n\")\n    build=subprocess.run([str(builder),\"BUILD\"],cwd=d,\n                         capture_output=True,text=True)\n    assert build.returncode==0,(build.stdout,build.stderr)\n    shutil.copy(d/\"dd:IDXOUT\",d/\"dd:IDXIN\")\n    original=hashlib.sha256((d/\"dd:IDXIN\").read_bytes()).hexdigest()\n    def run(*args):\n        return subprocess.run([str(planner),*map(str,args)],cwd=d,\n                              capture_output=True,text=True)\n    for chosen in ([3868,7736],[1,3868,7736],list(range(1,9))):\n        p=run(\"BATCH\",len(rows),64,*chosen)\n        assert p.returncode==0,(p.stdout,p.stderr)\n        lines=p.stdout.splitlines()\n        assert len(lines)==len(chosen),lines\n        for ln,num in zip(lines,chosen):\n            assert len(ln)<=80,(ln,len(ln))\n            tag,obj,header,count,typ,size,digest=ln.split()\n            assert tag==\"P201\"\n            assert (int(obj),int(header),int(count),int(typ),\n                    int(size),digest)==(num,*items[num])\n    for args,returncode in (\n        ((\"BATCH\",len(rows),64,3868,3868),4),\n        ((\"BATCH\",len(rows),64,3868),4),\n        ((\"BATCH\",len(rows),64,*range(1,10)),4),\n        ((\"BATCH\",len(rows),0,3868,7736),4),\n        ((\"BATCH\",len(rows)+1,64,3868,7736),8),\n        ((\"BATCH\",len(rows),1,3868,7736),8)\n    ):\n        res=run(*args)\n        assert res.returncode==returncode,(args,res.stdout,res.stderr)\n        assert not any(line.startswith(\"P201 \") for line in\n                       res.stdout.splitlines())\n    assert hashlib.sha256((d/\"dd:IDXIN\").read_bytes()).hexdigest()==original\nprint(\"M204 ONE-INDEX 2/3/8 TUPLE PARITY AND STRICT C89 PASS\")\nprint(\"M204 INVALID INDEX BOUNDS ALL-OR-NOTHING OUTPUT PASS\")\nprint(\"M204 CMS WRAPPER AUTH-THEN-CLEAN SOURCE GUARDS PASS\")\nprint(\"M204 TARGET CMS VALIDATION STILL REQUIRED\")\n",
    "M205": "#!/usr/bin/env python3\n\"\"\"M205: stratified index samples with full SHA and fail-closed source guards.\"\"\"\nfrom pathlib import Path\nimport hashlib\nimport shutil\nimport subprocess\nimport tempfile\n\nroot=Path(__file__).resolve().parents[1]\nsource=(root/\"src/GITP25M.C\").read_text()\nrex=(root/\"src/GITC25.EXEC\").read_text()\nassert max(map(len,source.splitlines()))<=80\nassert max(map(len,rex.splitlines()))<=80\nassert source.count('fopen(\"dd:IDXIN\",\"r\")')==1\nassert 'fopen(\"dd:STGIN\"' not in source\nassert 'fwrite(' not in source and 'fseek(' not in source\nassert \"if(rec-1UL!=expected)\" in source\nassert \"for(n=1;n<=total;n++)\" in source\nassert \"for(k=0;k<count;k++)\" in source\nassert \"picked[k]=0;\" in source\nassert \"if(!picked[k])\" in source\nassert \"M205 NO ELIGIBLE OBJECT IN BAND\" in source\nassert source.index(\"if(!picked[k])\")<source.index(\n    'printf(\"P201 ')\nassert \"start=((unsigned long)k*total)/(unsigned long)count+1UL;\" in source\nassert \"end=((unsigned long)(k+1)*total)/(unsigned long)count;\" in source\nfor token in (\n    \"parse upper arg fm mode max requested extra\",\n    \"if extra\\\\='' then exit 4\",\n    \"count=requested\",\n    \"if count<2 | count>8 then exit 4\",\n    \"'STATE M173NET STAGE G'\",\n    \"'STATE M174NET INDEX G'\",\n    \"'STATE GITP25M MODULE A'\",\n    \"'STATE GITBX9 MODULE A'\",\n    \"'PIPE CMS FILEDEF | STEM f.'\",\n    \"'FILEDEF IDXIN DISK M174NET INDEX G'\",\n    \"'PIPE CMS GITP25M SAMPLE 3864799' max count '| STEM plan.'\",\n    \"'FILEDEF IDXIN CLEAR'\",\n    \"readrc\\\\=0 | clearrc\\\\=0 | plan.0\\\\=count\",\n    \"low=trunc((i-1)*7736/count)+1\",\n    \"high=trunc(i*7736/count)\",\n    \"if n<low | n>high | hdr<1 | hdr>3864799 then exit 8\",\n    \"if cnt\\\\=trunc((size+31)/32) then exit 8\",\n    \"'GITB9 G' span.i\",\n    \"M205 SHA FAILED SCRATCH PRESERVED\",\n    \"'GITCLN SCRATCH'\",\n    \"M205 STRATIFIED FULL SHA CLEAN PASS\",\n):\n    assert token in rex,token\nassert rex.index(\"'GITB9 G' span.i\")<rex.index(\"'GITCLN SCRATCH'\")\nassert rex.index(\"if authrc\\\\=0 then do\")<rex.index(\"'GITCLN SCRATCH'\")\nfor token in (\"ERASE \", \"FSWRITE\", \"FORMAT \", \"PMAINT\", \"GIT600\"):\n    assert token not in rex\n\nwith tempfile.TemporaryDirectory(prefix=\"m205-\") as name:\n    d=Path(name)\n    compiler=[\"gcc\",\"-x\",\"c\",\"-std=c89\",\"-Wall\",\"-Wextra\",\"-Werror\"]\n    for file,exe in ((\"GITP25M.C\",\"planner\"),\n                     (\"GITPIDX.C\",\"builder\"),\n                     (\"GITVO7M.C\",\"verify\")):\n        subprocess.run(compiler+[str(root/\"src\"/file),\"-o\",str(d/exe)],\n                       check=True)\n    rows=[]\n    expected={}\n    for n in range(1,7737):\n        size=1148 if n==3868 else 291 if n==7736 else 33+n%93\n        body=n.to_bytes(4,\"big\")+bytes((n*11+i*23)%256\n                                 for i in range(size-4))\n        oid=hashlib.sha1(b\"blob \"+str(size).encode()+\n                         b\"\\0\"+body).hexdigest().upper()\n        header=len(rows)+1\n        count=(size+31)//32\n        expected[n]=(header,count,3,size,oid)\n        rows.append(\"OBJ %d 3 %d %s\"%(n,size,oid))\n        hx=body.hex().upper()\n        rows.extend(hx[k:k+64] for k in range(0,len(hx),64))\n    stage=d/\"dd:STGIN\"\n    stage.write_text(\"\\n\".join(rows)+\"\\n\")\n    result=subprocess.run([str(d/\"builder\"),\"BUILD\"],cwd=d,\n                          capture_output=True,text=True)\n    assert result.returncode==0,(result.stdout,result.stderr)\n    shutil.copy(d/\"dd:IDXOUT\",d/\"dd:IDXIN\")\n    stagehash=hashlib.sha256(stage.read_bytes()).hexdigest()\n    idxhash=hashlib.sha256((d/\"dd:IDXIN\").read_bytes()).hexdigest()\n    def planner(*argv):\n        return subprocess.run([str(d/\"planner\"),*map(str,argv)],\n                              cwd=d,capture_output=True,text=True)\n    for groups in (2,3,8):\n        res=planner(\"SAMPLE\",len(rows),64,groups)\n        assert res.returncode==0,(groups,res.stdout,res.stderr)\n        plans=res.stdout.splitlines()\n        assert len(plans)==groups\n        chosen=[]\n        for i,line in enumerate(plans):\n            assert len(line)<=80,(line,len(line))\n            tag,n,rec,cnt,typ,size,oid=line.split()\n            n,rec,cnt,typ,size=map(int,(n,rec,cnt,typ,size))\n            assert tag==\"P201\"\n            lower=i*7736//groups+1\n            upper=(i+1)*7736//groups\n            assert lower<=n<=upper,(groups,i,n)\n            assert (rec,cnt,typ,size,oid)==expected[n]\n            chosen.append(n)\n            assert 0<size<=2048 and 0<cnt<=64\n            # Host stand-in for M199: build scratch from exact stage\n            # records, then independently verify using the M197 C89 core.\n            scratch=d/\"dd:OBJIN\"\n            subset=rows[rec-1:rec+cnt]\n            assert len(subset)==cnt+1\n            scratch.write_text(\"\\n\".join(subset)+\"\\n\")\n            verify=subprocess.run(\n                [str(d/\"verify\"),\"VERIFY\",str(n),oid],\n                cwd=d,text=True,capture_output=True)\n            assert verify.returncode==0,(verify.stdout,verify.stderr)\n            assert \"M197 READ ONLY FULL OBJECT SHA1 PASS\" in verify.stdout\n            scratch.unlink()\n        assert len(set(chosen))==groups\n    for argv,rc in (\n        ((\"SAMPLE\",len(rows),64,1),4),\n        ((\"SAMPLE\",len(rows),64,9),4),\n        ((\"SAMPLE\",len(rows),0,8),4),\n        ((\"SAMPLE\",len(rows),1,8),8),\n        ((\"SAMPLE\",len(rows)+1,64,8),8)\n    ):\n        result=planner(*argv)\n        assert result.returncode==rc,(argv,result.stdout,result.stderr)\n        assert not any(x.startswith(\"P201 \") for x in\n                       result.stdout.splitlines())\n    assert hashlib.sha256(stage.read_bytes()).hexdigest()==stagehash\n    assert hashlib.sha256((d/\"dd:IDXIN\").read_bytes()).hexdigest()==idxhash\nprint(\"M205 2/3/8 STRATIFIED INDEX BANDS AND FULL OID SHA PASS\")\nprint(\"M205 STRICT C89 FAIL-CLOSED EMPTY BAND/RECORD COUNT PASS\")\nprint(\"M205 PROTECTED G AND SCRATCH OWNERSHIP STATIC GUARDS PASS\")\nprint(\"M205 CMS TARGET VALIDATION STILL PENDING\")\n",
    "M206": "#!/usr/bin/env python3\n\"\"\"M206: stratified index samples with full SHA and fail-closed source guards.\"\"\"\nfrom pathlib import Path\nimport hashlib\nimport shutil\nimport subprocess\nimport tempfile\n\nroot=Path(__file__).resolve().parents[1]\nsource=(root/\"src/GITP26M.C\").read_text()\nrex=(root/\"src/GITC26.EXEC\").read_text()\nassert max(map(len,source.splitlines()))<=80\nassert max(map(len,rex.splitlines()))<=80\nassert source.count('fopen(\"dd:IDXIN\",\"r\")')==1\nassert 'fopen(\"dd:STGIN\"' not in source\nassert 'fwrite(' not in source and 'fseek(' not in source\nassert \"if(rec-1UL!=expected)\" in source\nassert \"for(n=1;n<=total;n++)\" in source\nassert \"for(k=0;k<count;k++)\" in source\nassert \"picked[k]=0;\" in source\nassert \"if(!picked[k])\" in source\nassert \"M206 NO ELIGIBLE OBJECT IN BAND\" in source\nassert \"picked[32]\" in source\nassert \"num<2UL||num>32UL\" in source\nassert source.index(\"if(!picked[k])\")<source.index(\n    'printf(\"P201 ')\nassert \"start=((unsigned long)k*total)/(unsigned long)count+1UL;\" in source\nassert \"end=((unsigned long)(k+1)*total)/(unsigned long)count;\" in source\nfor token in (\n    \"parse upper arg fm mode max requested extra\",\n    \"if extra\\\\='' then exit 4\",\n    \"count=requested\",\n    \"if count<2 | count>32 then exit 4\",\n    \"'STATE M173NET STAGE G'\",\n    \"'STATE M174NET INDEX G'\",\n    \"'STATE GITP26M MODULE A'\",\n    \"'STATE GITBX9 MODULE A'\",\n    \"'PIPE CMS FILEDEF | STEM f.'\",\n    \"'FILEDEF IDXIN DISK M174NET INDEX G'\",\n    \"'PIPE CMS GITP26M SAMPLE 3864799' max count '| STEM plan.'\",\n    \"'FILEDEF IDXIN CLEAR'\",\n    \"readrc\\\\=0 | clearrc\\\\=0 | plan.0\\\\=count\",\n    \"low=trunc((i-1)*7736/count)+1\",\n    \"high=trunc(i*7736/count)\",\n    \"if n<low | n>high | hdr<1 | hdr>3864799 then exit 8\",\n    \"if cnt\\\\=trunc((size+31)/32) then exit 8\",\n    \"'GITB9 G' span.i\",\n    \"M206 SHA FAILED SCRATCH PRESERVED\",\n    \"'GITCLN SCRATCH'\",\n    \"M206 STRATIFIED FULL SHA CLEAN PASS\",\n):\n    assert token in rex,token\nassert rex.index(\"'GITB9 G' span.i\")<rex.index(\"'GITCLN SCRATCH'\")\nassert rex.index(\"if authrc\\\\=0 then do\")<rex.index(\"'GITCLN SCRATCH'\")\nfor token in (\"ERASE \", \"FSWRITE\", \"FORMAT \", \"PMAINT\", \"GIT600\"):\n    assert token not in rex\n\nwith tempfile.TemporaryDirectory(prefix=\"m205-\") as name:\n    d=Path(name)\n    compiler=[\"gcc\",\"-x\",\"c\",\"-std=c89\",\"-Wall\",\"-Wextra\",\"-Werror\"]\n    for file,exe in ((\"GITP26M.C\",\"planner\"),\n                     (\"GITPIDX.C\",\"builder\"),\n                     (\"GITVO7M.C\",\"verify\")):\n        subprocess.run(compiler+[str(root/\"src\"/file),\"-o\",str(d/exe)],\n                       check=True)\n    rows=[]\n    expected={}\n    for n in range(1,7737):\n        size=1148 if n==3868 else 291 if n==7736 else 33+n%93\n        body=n.to_bytes(4,\"big\")+bytes((n*11+i*23)%256\n                                 for i in range(size-4))\n        oid=hashlib.sha1(b\"blob \"+str(size).encode()+\n                         b\"\\0\"+body).hexdigest().upper()\n        header=len(rows)+1\n        count=(size+31)//32\n        expected[n]=(header,count,3,size,oid)\n        rows.append(\"OBJ %d 3 %d %s\"%(n,size,oid))\n        hx=body.hex().upper()\n        rows.extend(hx[k:k+64] for k in range(0,len(hx),64))\n    stage=d/\"dd:STGIN\"\n    stage.write_text(\"\\n\".join(rows)+\"\\n\")\n    result=subprocess.run([str(d/\"builder\"),\"BUILD\"],cwd=d,\n                          capture_output=True,text=True)\n    assert result.returncode==0,(result.stdout,result.stderr)\n    shutil.copy(d/\"dd:IDXOUT\",d/\"dd:IDXIN\")\n    stagehash=hashlib.sha256(stage.read_bytes()).hexdigest()\n    idxhash=hashlib.sha256((d/\"dd:IDXIN\").read_bytes()).hexdigest()\n    def planner(*argv):\n        return subprocess.run([str(d/\"planner\"),*map(str,argv)],\n                              cwd=d,capture_output=True,text=True)\n    for groups in (2,3,8,16,32):\n        res=planner(\"SAMPLE\",len(rows),64,groups)\n        assert res.returncode==0,(groups,res.stdout,res.stderr)\n        plans=res.stdout.splitlines()\n        assert len(plans)==groups\n        chosen=[]\n        for i,line in enumerate(plans):\n            assert len(line)<=80,(line,len(line))\n            tag,n,rec,cnt,typ,size,oid=line.split()\n            n,rec,cnt,typ,size=map(int,(n,rec,cnt,typ,size))\n            assert tag==\"P201\"\n            lower=i*7736//groups+1\n            upper=(i+1)*7736//groups\n            assert lower<=n<=upper,(groups,i,n)\n            assert (rec,cnt,typ,size,oid)==expected[n]\n            chosen.append(n)\n            assert 0<size<=2048 and 0<cnt<=64\n            # Host stand-in for M199: build scratch from exact stage\n            # records, then independently verify using the M197 C89 core.\n            scratch=d/\"dd:OBJIN\"\n            subset=rows[rec-1:rec+cnt]\n            assert len(subset)==cnt+1\n            scratch.write_text(\"\\n\".join(subset)+\"\\n\")\n            verify=subprocess.run(\n                [str(d/\"verify\"),\"VERIFY\",str(n),oid],\n                cwd=d,text=True,capture_output=True)\n            assert verify.returncode==0,(verify.stdout,verify.stderr)\n            assert \"M197 READ ONLY FULL OBJECT SHA1 PASS\" in verify.stdout\n            scratch.unlink()\n        assert len(set(chosen))==groups\n    for argv,rc in (\n        ((\"SAMPLE\",len(rows),64,1),4),\n        ((\"SAMPLE\",len(rows),64,33),4),\n        ((\"SAMPLE\",len(rows),0,8),4),\n        ((\"SAMPLE\",len(rows),1,8),8),\n        ((\"SAMPLE\",len(rows)+1,64,8),8)\n    ):\n        result=planner(*argv)\n        assert result.returncode==rc,(argv,result.stdout,result.stderr)\n        assert not any(x.startswith(\"P201 \") for x in\n                       result.stdout.splitlines())\n    # Make the entire first of 32 bands exceed the M199 bounds,\n    # while maintaining a complete syntactically valid PIDX1.\n    # No individual P201 record may escape after that failure.\n    lines=(d/\"dd:IDXIN\").read_text().splitlines()\n    larger=0\n    mutated=[]\n    for line in lines:\n        fields=line.split()\n        if len(fields)==6 and fields[0]==\"OID\":\n            ordinal=int(fields[2])\n            if 1<=ordinal<=7736//32:\n                oldsize=int(fields[4])\n                larger+=((2100+31)//32)-((oldsize+31)//32)\n                fields[4]=\"2100\"\n                line=\" \".join(fields)\n        mutated.append(line)\n    (d/\"dd:IDXIN\").write_text(\"\\n\".join(mutated)+\"\\n\")\n    rejected=planner(\"SAMPLE\",len(rows)+larger,64,32)\n    assert rejected.returncode==8,(rejected.stdout,rejected.stderr)\n    assert \"M206 NO ELIGIBLE OBJECT IN BAND\" in rejected.stdout\n    assert not any(x.startswith(\"P201 \") for x in\n                   rejected.stdout.splitlines())\n    shutil.copy(d/\"dd:IDXOUT\",d/\"dd:IDXIN\")\n    assert hashlib.sha256(stage.read_bytes()).hexdigest()==stagehash\n    assert hashlib.sha256((d/\"dd:IDXIN\").read_bytes()).hexdigest()==idxhash\nprint(\"M206 2/3/8/16/32 STRATIFIED INDEX BANDS AND FULL OID SHA PASS\")\nprint(\"M206 STRICT C89 FAIL-CLOSED EMPTY BAND/RECORD COUNT PASS\")\nprint(\"M206 PROTECTED G AND SCRATCH OWNERSHIP STATIC GUARDS PASS\")\nprint(\"M206 CMS TARGET VALIDATION STILL PENDING\")\n",
    "M203": "#!/usr/bin/env python3\n\"\"\"M203: bounded 2..8-object CMS REXX verification order guard.\"\"\"\nfrom pathlib import Path\n\nROOT=Path(__file__).resolve().parents[1]\ncode=(ROOT/\"src/GITC23.EXEC\").read_text()\nassert max(map(len,code.splitlines()))<=80\ntokens=[\n \"parse upper arg fm mode limit members\",\n \"count=words(members)\",\n \"count<2 | count>8\",\n \"objs.i=word(members,i)\",\n \"objs.i<1 | objs.i>7736\",\n \"if objs.i=objs.j then do\",\n \"'STATE GITP21M MODULE A'\",\n \"'STATE GITBX9 MODULE A'\",\n \"'STATE GITVO7M MODULE A'\",\n \"'STATE GITVRAW DATA A'\",\n \"'STATE GITR199 DATA A'\",\n \"'PIPE CMS FILEDEF | STEM defs.'\",\n \"'GITP21 G' objs.i limit 'CHECK'\",\n \"M203 ALL INDEX CHECKS PASS\",\n \"M203 CHECK ONLY NO SCRATCH PASS\",\n \"'GITP21 G' obj limit\",\n \"M203 SHA GATE FAIL SCRATCH PRESERVED\",\n \"'GITCLN SCRATCH'\",\n \"M203 FULL OBJECT SHA VERIFIED\",\n \"M203 CLEAN VERIFIED\",\n \"M203 BOUNDED FULL SHA CLEAN PASS\"\n]\nfor token in tokens:\n    assert token in code,token\nassert code.count(\"'GITCLN SCRATCH'\")==1\nassert code.count(\"'GITP21 G' obj limit\")==1\nassert code.count(\"'GITP21 G' objs.i limit 'CHECK'\")==1\npre,post=code.split(\"if mode='CHECK' then do\",1)\nassert \"M203 ALL INDEX CHECKS PASS\" in pre\nassert post.index(\"'GITP21 G' obj limit\")<post.index(\n    \"'GITCLN SCRATCH'\")\nassert post.index(\"if s\\\\=0 then do\")<post.index(\n    \"'GITCLN SCRATCH'\")\nfor token in (\"M173NET\", \"M174NET\", \"GIT600\",\n              \"FSWRITE\", \"FSREAD\", \"OPENTYP=REPLACE\"):\n    assert token not in code,token\ndef valid(items):\n    if not 2<=len(items)<=8: return False\n    if any(not isinstance(x,int) or isinstance(x,bool) or\n           x<1 or x>7736 for x in items): return False\n    return len(set(items))==len(items)\nfor seq in ([3868,7736],[1,3868,7736],list(range(1,9))):\n    assert valid(seq)\nfor seq in ([1],list(range(1,10)),[1,1],[1,7737]):\n    assert not valid(seq)\ndef simulate(items,failcheck=-1,failsha=-1,failclean=-1,\n             checking=False):\n    if not valid(items):return \"BAD\",[],False\n    events=[]\n    scratch=False\n    for i,obj in enumerate(items):\n        events.append((\"CHECK\",obj))\n        if i==failcheck:return \"CHECK_FAIL\",events,scratch\n    if checking:return \"CHECK_PASS\",events,scratch\n    for i,obj in enumerate(items):\n        events.append((\"SHA\",obj))\n        scratch=True\n        if i==failsha:return \"SHA_FAIL\",events,scratch\n        events.append((\"CLEAN\",obj))\n        if i==failclean:return \"CLEAN_FAIL\",events,scratch\n        scratch=False\n    return \"PASS\",events,scratch\nfor seq in ([3868,7736],[1,3868,7736],list(range(1,9))):\n    a,e,s=simulate(seq)\n    assert a==\"PASS\" and not s\n    assert [x[0] for x in e[:len(seq)]]==[\"CHECK\"]*len(seq)\n    a,e,s=simulate(seq,checking=True)\n    assert a==\"CHECK_PASS\" and not s\n    assert len(e)==len(seq)\n    a,e,s=simulate(seq,failcheck=len(seq)-1)\n    assert a==\"CHECK_FAIL\" and not s\n    assert all(x[0]==\"CHECK\" for x in e)\n    a,e,s=simulate(seq,failsha=0)\n    assert a==\"SHA_FAIL\" and s and (\"CLEAN\",seq[0]) not in e\n    a,e,s=simulate(seq,failclean=0)\n    assert a==\"CLEAN_FAIL\" and s and (\"SHA\",seq[1]) not in e\nprint(\"M203 BOUNDED DISTINCT OBJECTS, PREFLIGHT AND SHA HOST PASS\")\nprint(\"M203 FAILED SHA/CLEANUP PRESERVES SCRATCH AND STOPS\")\nprint(\"M203 REAL CMS TARGET CHECK/RUN STILL PENDING\")\n"
}

